bio("said-ibn-musayyib", [
 ("هُوَ سَعِيدُ بْنُ الْمُسَيِّبِ، مِنْ قُرَيْشٍ، أَبُو مُحَمَّدٍ.", "Er ist Saʿid ibn al-Musayyib, aus Quraisch, Abu Muhammad.", 3370),
 ("كَانَ عَالِمَ أَهْلِ الْمَدِينَةِ، وَسَيِّدَ التَّابِعِينَ فِي زَمَانِهِ.", "Er war der Gelehrte der Leute von Medina und der Herr der Tabiʿin seiner Zeit.", 3371),
 ("وُلِدَ فِي خِلَافَةِ عُمَرَ بْنِ الْخَطَّابِ.", "Er wurde während des Kalifats von ʿUmar ibn al-Khattab geboren.", 3371),
 ("قَالَ: مَا فَاتَتْنِي الصَّلَاةُ فِي جَمَاعَةٍ مُنْذُ أَرْبَعِينَ سَنَةً.", "Er sagte: Seit vierzig Jahren habe ich kein Gemeinschaftsgebet verpasst.", 3374),
 ("وَكَانَ زَوْجَ ابْنَةِ أَبِي هُرَيْرَةَ، وَأَكْثَرُ رِوَايَتِهِ عَنْهُ.", "Er war mit der Tochter Abu Hurayras verheiratet, und das meiste, was er überlieferte, stammt von ihm.", 3377),
 ("وَلَمْ يَكُنْ يَذْهَبُ إِلَى الْخُلَفَاءِ، حَتَّى عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ تَرَكَهُ.", "Er ging nicht zu den Kalifen; selbst ʿAbd al-Malik ibn Marwan ließ ihn in Ruhe.", 3379),
 ("تُوُفِّيَ سَنَةَ ثَلَاثٍ وَتِسْعِينَ، وَقِيلَ غَيْرُ ذَلِكَ.", "Er starb im Jahr 93; es gibt auch andere Angaben.", 3399),
], [
 ("athar", "عَالِمُ أَهْلِ المَدِيْنَةِ", "Der Gelehrte der Leute von Medina. (adh-Dhahabi)", 3370),
 ("athar", "مَا فَاتَتْنِي الصَّلاَةُ فِي جَمَاعَةٍ مُنْذُ أَرْبَعِيْنَ سَنَةً", "Seit vierzig Jahren habe ich kein Gemeinschaftsgebet verpasst. (Saʿid ibn al-Musayyib)", 3374, E),
])
bio("uways", [
 ("هُوَ أُوَيْسُ بْنُ عَامِرٍ الْقَرَنِيُّ، مِنْ مُرَادٍ، مِنْ أَهْلِ الْيَمَنِ.", "Er ist Uways ibn ʿAmir al-Qarani, aus dem Stamm Murad im Jemen.", 3173),
 ("كَانَ قُدْوَةً زَاهِدًا، وَسَيِّدَ التَّابِعِينَ فِي زَمَانِهِ.", "Er war ein Vorbild an Weltverzicht und der Herr der Tabiʿin seiner Zeit.", 3172),
 ("لَمْ يَرَ النَّبِيَّ ﷺ، وَلَكِنَّهُ وَفَدَ عَلَى عُمَرَ.", "Er sah den Propheten ﷺ nicht, aber er kam zu ʿUmar.", 3173),
 ("كَانَ عُمَرُ يَسْأَلُ أَهْلَ الْيَمَنِ: هَلْ فِيكُمْ أَحَدٌ مِنْ قَرَنٍ؟", "ʿUmar fragte die Leute aus dem Jemen: Ist jemand aus Qaran unter euch?", 3173),
 ("لِأَنَّهُ سَمِعَ النَّبِيَّ ﷺ يَقُولُ: إِنَّ خَيْرَ التَّابِعِينَ رَجُلٌ يُقَالُ لَهُ أُوَيْسٌ، وَلَهُ وَالِدَةٌ.", "Denn er hatte den Propheten ﷺ sagen hören: Der beste der Tabiʿin ist ein Mann namens Uways, der eine Mutter hat.", 3173),
 ("فَلَمَّا وَجَدَهُ قَالَ لَهُ عُمَرُ: اسْتَغْفِرْ لِي.", "Als ʿUmar ihn fand, sagte er zu ihm: Bitte (Allah) um Vergebung für mich.", 3173),
 ("وَكَانَ مِنْ أَوْلِيَاءِ اللَّهِ الْمُتَّقِينَ، وَمِنْ عِبَادِهِ الْمُخْلَصِينَ.", "Er gehörte zu den gottesfürchtigen Freunden Allahs und zu Seinen aufrichtigen Dienern.", 3173),
], [
 ("hadith", "إِنَّ خَيْرَ التَّابِعِيْنَ رَجُلٌ يُقَالُ لَهُ: أُوَيْسٌ، وَلَهُ وَالِدَةٌ", "Der beste der Tabiʿin ist ein Mann namens Uways, der eine Mutter hat.", 3173, "Muslim (Sigel „م“ bei adh-Dhahabi)"),
 ("athar", "وَقَدْ كَانَ مِنْ أَوْلِيَاءِ اللهِ المُتَّقِيْنَ، وَمِنْ عِبَادِهِ المُخْلَصِيْنَ", "Er gehörte zu den gottesfürchtigen Freunden Allahs und zu Seinen aufrichtigen Dienern. (adh-Dhahabi)", 3173),
])
bio("hasan-basri", [
 ("هُوَ الْحَسَنُ بْنُ أَبِي الْحَسَنِ يَسَارٍ، أَبُو سَعِيدٍ الْبَصْرِيُّ.", "Er ist al-Hasan ibn Abi l-Hasan Yasar, Abu Saʿid aus Basra.", 3716),
 ("وُلِدَ فِي الْمَدِينَةِ قَبْلَ نِهَايَةِ خِلَافَةِ عُمَرَ بِسَنَتَيْنِ.", "Er wurde in Medina geboren, zwei Jahre vor dem Ende von ʿUmars Kalifat.", 3717),
 ("وَكَانَ أَبُوهُ يَسَارٌ مِنْ سَبْيِ مَيْسَانَ، ثُمَّ أُعْتِقَ.", "Sein Vater Yasar war ein Kriegsgefangener aus Maysan und wurde später freigelassen.", 3717),
 ("كَانَ عَالِمًا فَقِيهًا ثِقَةً، عَابِدًا، كَثِيرَ الْعِلْمِ، فَصِيحًا.", "Er war gelehrt, rechtskundig, zuverlässig, ein Mann der Anbetung, reich an Wissen und sprachgewandt.", 3725),
 ("وَكَانَ الزُّهَّادُ يَأْتُونَهُ وَيَسْمَعُونَ كَلَامَهُ فِي الزُّهْدِ.", "Die Asketen kamen zu ihm und hörten seine Worte über den Weltverzicht.", 3732),
 ("تُوُفِّيَ فِي رَجَبٍ سَنَةَ عَشْرٍ وَمِئَةٍ.", "Er starb im Radschab des Jahres 110.", 3740),
], [
 ("athar", "كَانَ الحَسَنُ -﵀- جَامِعًا، عَالِمًا، رَفِيْعًا، فَقِيْهًا، ثِقَةً، حُجَّةً، مَأْمُوْنًا، عَابِدًا، نَاسِكًا، كَثِيْرَ العِلْمِ، فَصِيْحًا", "Al-Hasan – Allah erbarme sich seiner – war umfassend gebildet, gelehrt, angesehen, rechtskundig, zuverlässig, ein Beweis, vertrauenswürdig, gottesdienstlich, asketisch, reich an Wissen und sprachgewandt. (Ibn Saʿd)", 3725),
])
